# Try hf-mirror with proper User-Agent header
import urllib.request
req = urllib.request.Request(
    'https://hf-mirror.com/EleutherAI/pythia-410m-seed1/resolve/main/config.json',
    headers={'User-Agent': 'Mozilla/5.0'}
)
try:
    r = urllib.request.urlopen(req, timeout=10)
    print(f'hf-mirror with UA: OK, status={r.status}')
except Exception as e:
    print(f'hf-mirror with UA: {e}')

# Try without proxy for hf-mirror
import os
for k in ['http_proxy', 'https_proxy', 'HTTP_PROXY', 'HTTPS_PROXY']:
    os.environ.pop(k, None)
req2 = urllib.request.Request(
    'https://hf-mirror.com/EleutherAI/pythia-410m-seed1/resolve/main/config.json',
    headers={'User-Agent': 'Mozilla/5.0'}
)
try:
    r = urllib.request.urlopen(req2, timeout=10)
    print(f'hf-mirror no-proxy: OK, status={r.status}')
except Exception as e:
    print(f'hf-mirror no-proxy: {e}')
"

source /etc/network_turbo && source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && export HF_HOME=/root/autodl-tmp/.hf_cache && export HF_HUB_DISABLE_XET=1 && export REQUESTS_CA_BUNDLE=/etc/ssl/certs/ca-certificates.crt && export SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt && python3 -c "
from huggingface_hub import HfApi
api = HfApi()
# Try various searches
for term in ['polypythias', 'polypythia-evals', 'pythia-evals']:
    ds = list(api.list_datasets(search=term, limit=10))
    if ds:
        for d in ds:
            print(f'  {d.id}')
    else:
        print(f'  No results for: {term}')
print('---')
# Also check EleutherAI repos
repos = list(api.list_datasets(author='EleutherAI', limit=50))
for r in repos:
    if 'pythia' in r.id.lower() or 'eval' in r.id.lower():
        print(f'  {r.id}')
"

